package in.tucor.api.buyer;import org.springframework.security.core.Authentication;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/buyer/saved-listings") public class BuyerSavedListingController{private final BuyerSavedListingRepository saved;private final MarketListingRepository listings;public BuyerSavedListingController(BuyerSavedListingRepository s,MarketListingRepository l){saved=s;listings=l;}@GetMapping public List<String> all(Authentication a){UUID u=UUID.fromString(a.getName());return saved.findByBuyerIdOrderByCreatedAtDesc(u).stream().map(x->listings.findById(x.listingId).map(l->l.publicId).orElse(null)).filter(Objects::nonNull).toList();}@PostMapping("/{publicId}") public void add(Authentication a,@PathVariable String publicId){UUID u=UUID.fromString(a.getName());MarketListing l=listings.findByPublicId(publicId).orElseThrow(()->new IllegalArgumentException("Listing not found"));BuyerSavedListing x=new BuyerSavedListing();x.buyerId=u;x.listingId=l.id;saved.save(x);}@Transactional @DeleteMapping("/{publicId}") public void remove(Authentication a,@PathVariable String publicId){UUID u=UUID.fromString(a.getName());MarketListing l=listings.findAll().stream().filter(x->x.publicId.equals(publicId)).findFirst().orElseThrow();saved.deleteByBuyerIdAndListingId(u,l.id);}}